'use client'

import * as React from 'react'

import { useInViewOnce } from './use-reduced-motion'
import './marker-highlight.css'

export type MarkerHighlightProps = {
    children: React.ReactNode
    /** `mark` tells assistive tech the text is highlighted; use `span` for purely visual emphasis. */
    as?: 'mark' | 'span'
    /** Marker colour. Keep it light enough for the text on top to keep its contrast. */
    color?: string
    /** Milliseconds for the stroke. */
    duration?: number
    delay?: number
    className?: string
}

const MarkerHighlight = ({ children, as: Tag = 'mark', color = 'rgba(250, 204, 21, 0.45)', duration = 900, delay = 0, className }: MarkerHighlightProps) => {
    const ref = React.useRef<HTMLElement | null>(null)
    const [drawn, setDrawn] = React.useState(false)
    useInViewOnce(ref, () => setDrawn(true), !drawn, 0.6)

    return <Tag
        ref={ref as React.Ref<never>}
        className={['rad-fx-marker', className].filter(Boolean).join(' ')}
        data-state={drawn ? 'drawn' : 'idle'}
        style={{ '--rad-fx-marker-color': color, '--rad-fx-marker-duration': `${duration}ms`, '--rad-fx-marker-delay': `${delay}ms` } as React.CSSProperties}
    >
        {children}
    </Tag>
}

export default MarkerHighlight

.rad-fx-marker {
    color: inherit;
    padding: 0 0.15em;
    margin: 0 -0.15em;
    border-radius: 0.2em;
    background-color: transparent;
    background-image: linear-gradient(100deg, transparent 0.2em, var(--rad-fx-marker-color) 0.4em, var(--rad-fx-marker-color) calc(100% - 0.3em), transparent);
    background-repeat: no-repeat;
    background-position: 0 85%;
    background-size: 0% 75%;

    /* Each line of a wrapped highlight gets its own stroke. */
    box-decoration-break: clone;
    box-decoration-break: clone;
    transition: background-size var(--rad-fx-marker-duration, 900ms) cubic-bezier(0.6, 0.1, 0.2, 1) var(--rad-fx-marker-delay, 0ms);
}

.rad-fx-marker[data-state='drawn'] { background-size: 100% 75%; }

@media (prefers-reduced-motion: reduce) {
    .rad-fx-marker { transition: none; background-size: 100% 75%; }
}

[data-rad-fx-motion='reduce'] .rad-fx-marker { transition: none; background-size: 100% 75%; }
